-- Manufacturer-owned lead review, part 3: existing functions rewired.
-- Generated by scripts/gen_review_migration.py from the original definitions;
-- each edit is asserted so a changed anchor fails generation loudly.

create or replace function public.enqueue_outbound_message(
  p_conversation uuid,
  p_body text,
  p_template uuid default null,
  p_actor public.message_actor default null,
  p_media_path text default null,
  p_media_type text default null,
  p_media_filename text default null,
  p_template_params jsonb default null,
  p_idempotency_key text default null,
  p_turn uuid default null,
  p_ai_action uuid default null
)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_conv public.conversations%rowtype;
  v_mfr public.manufacturers%rowtype;
  v_template public.message_templates%rowtype;
  v_consent public.consent_status;
  v_actor public.message_actor;
  v_cap integer;
  v_sent_today integer;
  v_id uuid;
  v_body text := p_body;
begin
  if p_idempotency_key is not null then
    select id into v_id from public.messages where idempotency_key = p_idempotency_key;
    if v_id is not null then
      return v_id;
    end if;
  end if;

  select * into v_conv from public.conversations where id = p_conversation for update;
  if not found then
    perform public.app_error('not_found', 'Conversation not found', 'conversation_id');
  end if;

  -- Caller identity and actor
  if public.is_trusted() then
    v_actor := coalesce(p_actor, 'ai');
  else
    if v_conv.manufacturer_id is distinct from public.auth_mid() then
      perform public.app_error('forbidden', 'Conversation belongs to another manufacturer', 'conversation_id');
    end if;
    if not public.rep_can_see_conversation(p_conversation) then
      perform public.app_error('forbidden', 'This lead is not assigned to you', 'conversation_id');
    end if;
    v_actor := case when public.auth_role() = 'rep' then 'rep'::public.message_actor else 'owner'::public.message_actor end;
  end if;

  select * into v_mfr from public.manufacturers where id = v_conv.manufacturer_id;

  if v_actor = 'ai' and v_conv.ai_paused then
    perform public.app_error('ai_paused', 'The AI is paused on this thread until a human resumes it', 'conversation_id');
  end if;

  -- Consent gate
  v_consent := public.consent_status_for(v_conv.contact_id, v_conv.channel);
  if v_consent not in ('engaged', 'opted_in') then
    perform public.app_error('consent_required',
      format('Contact consent is %s; WhatsApp needs engaged or opted_in', v_consent), 'consent');
  end if;

  -- Lead review gate: a discovered prospect is contacted only after the
  -- manufacturer approved it. A buyer who wrote first may always be answered.
  if v_conv.last_inbound_at is null
     and coalesce((select review_status::text from public.prospects where id = v_conv.prospect_id), '') <> 'approved' then
    perform public.app_error('prospect_not_approved',
      'This prospect has not been approved in Lead Review; outreach is blocked until it is', 'prospect');
  end if;

  -- Session window or approved template
  if p_template is not null then
    select * into v_template from public.message_templates
    where id = p_template and (manufacturer_id is null or manufacturer_id = v_conv.manufacturer_id);
    if not found or v_template.meta_status <> 'approved' then
      perform public.app_error('template_not_approved', 'Template is not Meta approved', 'template_id');
    end if;
    if v_body is null then
      v_body := v_template.body;
    end if;
  elsif v_conv.window_expires_at is null or now() >= v_conv.window_expires_at then
    perform public.app_error('window_closed',
      'The 24 hour session window is closed; use an approved template', 'template_id');
  end if;

  if coalesce(trim(v_body), '') = '' and p_media_path is null then
    perform public.app_error('empty_message', 'Message needs a body or an attachment', 'body');
  end if;

  -- Daily outbound cap per manufacturer
  v_cap := coalesce((v_mfr.settings ->> 'daily_outbound_cap')::integer, 500);
  select count(*) into v_sent_today from public.messages
  where manufacturer_id = v_conv.manufacturer_id and direction = 'outbound'
    and status not in ('blocked', 'cancelled', 'failed')
    and created_at >= date_trunc('day', now() at time zone 'Asia/Kolkata') at time zone 'Asia/Kolkata';
  if v_sent_today >= v_cap then
    perform public.app_error('daily_cap_reached', format('Daily outbound cap of %s reached', v_cap), null);
  end if;

  insert into public.messages (manufacturer_id, conversation_id, direction, body, media_path, media_type,
    media_filename, template_id, template_params, status, actor, actor_user_id, idempotency_key, turn_id, ai_action_id)
  values (v_conv.manufacturer_id, p_conversation, 'outbound', v_body, p_media_path, p_media_type,
    p_media_filename, p_template, p_template_params, 'queued', v_actor,
    case when v_actor in ('rep', 'owner') then auth.uid() end, p_idempotency_key, p_turn, p_ai_action)
  returning id into v_id;

  if p_template is not null then
    update public.message_templates set usage_count = usage_count + 1 where id = p_template;
  end if;

  update public.conversations
  set last_outbound_at = now(), last_message_preview = left(coalesce(v_body, '[attachment]'), 140)
  where id = p_conversation;

  perform pgmq.send('outbound_messages', jsonb_build_object('message_id', v_id));
  return v_id;
end
$$;

create or replace function public.create_campaign(
  p_objective text,
  p_product_ids uuid[],
  p_city text,
  p_state text,
  p_category text default null,
  p_target_count integer default 75,
  p_parsed jsonb default '{}'::jsonb,
  p_name text default null
)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_mid uuid := public.auth_mid();
  v_id uuid;
  v_source record;
  v_jobs integer := 0;
  v_job uuid;
begin
  if not public.is_manager() then
    perform public.app_error('forbidden', 'Only an owner or sales head can start a campaign', null);
  end if;
  if coalesce(trim(p_objective), '') = '' then
    perform public.app_error('objective_required', 'Describe the market you want to sell into', 'objective');
  end if;
  if coalesce(trim(p_city), '') = '' then
    perform public.app_error('city_required', 'Pick a city for this campaign', 'city');
  end if;
  if p_product_ids is null or cardinality(p_product_ids) = 0 then
    perform public.app_error('products_required', 'Pick at least one product', 'product_ids');
  end if;
  if exists (select 1 from unnest(p_product_ids) pid
             where not exists (select 1 from public.products where id = pid and manufacturer_id = v_mid and status = 'active')) then
    perform public.app_error('invalid_product', 'A selected product is not active in your catalogue', 'product_ids');
  end if;
  if p_target_count is null or p_target_count < 1 or p_target_count > 500 then
    perform public.app_error('invalid_target', 'Target count must be between 1 and 500', 'target_count');
  end if;

  insert into public.campaigns (manufacturer_id, name, product_ids, objective_text, parsed_intent, target_geo,
    target_city, target_state, target_category, target_count, status, status_detail, created_by)
  values (v_mid, coalesce(nullif(trim(p_name), ''), initcap(p_city) || ' · ' || to_char(now() at time zone 'Asia/Kolkata', 'Mon YYYY')),
    p_product_ids, p_objective, coalesce(p_parsed, '{}'::jsonb),
    jsonb_build_object('city', p_city, 'state', p_state), initcap(trim(p_city)), p_state, p_category, p_target_count,
    'discovering', 'Finding buyers', auth.uid())
  returning id into v_id;

  for v_source in
    select * from public.sources
    where enabled and coalesce(trim(lawful_basis), '') <> '' and adapter <> 'csv_upload'
  loop
    insert into public.campaign_jobs (manufacturer_id, campaign_id, step, source_id)
    values (v_mid, v_id, 'ingest', v_source.id)
    returning id into v_job;
    perform pgmq.send('ingest', jsonb_build_object('campaign_job_id', v_job));
    v_jobs := v_jobs + 1;
  end loop;

  if v_jobs = 0 then
    update public.campaigns
    set status_detail = 'No automatic source is enabled: import your own buyer list in Lead Review', stalled_step = 'ingest'
    where id = v_id;
    perform public.notify_users(v_mid, public.permitted_users(v_mid, 'review_leads'), 'campaign_needs_sourcing',
      'Add buyers to your campaign', p_objective, '/leads?campaign=' || v_id || '&import=1',
      'campaign_sourcing:' || v_id, '{in_app,email}');
  end if;

  insert into public.product_events (manufacturer_id, user_id, name, properties)
  values (v_mid, auth.uid(), 'campaign_started', jsonb_build_object('campaign_id', v_id, 'sources', v_jobs));
  return v_id;
end
$$;

create or replace function public.normalize_campaign_records(p_campaign uuid)
returns jsonb
language plpgsql security definer
set search_path = public, extensions
as $$
declare
  v_campaign public.campaigns%rowtype;
  r public.raw_records%rowtype;
  p jsonb;
  v_name text;
  v_norm text;
  v_phone text;
  v_city text;
  v_match uuid;
  v_sim numeric;
  v_prospect uuid;
  v_contact uuid;
  v_created integer := 0;
  v_merged integer := 0;
  v_review integer := 0;
  v_rejected integer := 0;
  v_conf text;
begin
  select * into v_campaign from public.campaigns where id = p_campaign;
  if not found then
    perform public.app_error('not_found', 'Campaign not found', 'campaign_id');
  end if;
  if not (public.is_trusted()
          or (public.has_permission('review_leads') and v_campaign.manufacturer_id = public.auth_mid())) then
    perform public.app_error('forbidden', 'Not allowed', null);
  end if;

  for r in select * from public.raw_records where campaign_id = p_campaign and status = 'new' for update skip locked loop
    p := r.payload;
    v_name := nullif(trim(p ->> 'name'), '');
    v_norm := public.normalize_business_name(v_name);
    v_phone := public.normalize_phone_e164(p ->> 'phone');
    v_city := initcap(trim(coalesce(p ->> 'city', v_campaign.target_city)));
    v_conf := case when coalesce((p ->> 'verified')::boolean, false) or coalesce(p ->> 'source_url', '') <> '' then 'verified' else 'inferred' end;

    if v_norm is null then
      update public.raw_records set status = 'rejected', error = 'missing name' where id = r.id;
      v_rejected := v_rejected + 1;
      continue;
    end if;

    -- exact phone match first
    v_match := null;
    v_sim := null;
    if v_phone is not null then
      select c.prospect_id into v_match from public.contacts c
      where c.manufacturer_id = r.manufacturer_id and c.phone_e164 = v_phone limit 1;
      if v_match is not null then
        v_sim := 1;
      end if;
    end if;
    if v_match is null then
      select id, similarity(normalized_name, v_norm) into v_match, v_sim
      from public.prospects
      where manufacturer_id = r.manufacturer_id
        and normalized_name % v_norm
        and (city is null or v_city is null or lower(city) = lower(v_city))
      order by similarity(normalized_name, v_norm) desc
      limit 1;
    end if;

    if v_match is not null and v_sim > 0.85 then
      -- auto merge, keeping the highest confidence source
      update public.prospects pr set
        confidence = case when v_conf = 'verified' then 'verified' else pr.confidence end,
        source_url = coalesce(pr.source_url, p ->> 'source_url'),
        address = coalesce(pr.address, p ->> 'address'),
        pincode = coalesce(pr.pincode, p ->> 'pincode'),
        website = coalesce(pr.website, p ->> 'website'),
        signals = coalesce(p -> 'signals', '{}'::jsonb) || pr.signals
      where pr.id = v_match;
      update public.raw_records set status = 'merged', prospect_id = v_match where id = r.id;
      v_merged := v_merged + 1;
    elsif v_match is not null and v_sim >= 0.6 then
      -- Uncertain: keep the record but flag it for the manufacturer's decision.
      v_prospect := public.create_prospect_from_raw(r.id);
      update public.prospects
      set review_flags = (select array_agg(distinct f) from unnest(review_flags || array['possible_duplicate']) f),
          review_status = 'needs_review',
          attention_reason = format('Possible duplicate of %s (%s%% similar)',
                                    (select name from public.prospects where id = v_match), round(v_sim * 100))
      where id = v_prospect;
      insert into public.merge_candidates (manufacturer_id, campaign_id, raw_record_id, prospect_id, candidate_prospect_id, similarity)
      values (r.manufacturer_id, p_campaign, r.id, v_match, v_prospect, round(v_sim, 3))
      on conflict do nothing;
      v_review := v_review + 1;
    else
      v_prospect := public.create_prospect_from_raw(r.id);
      v_created := v_created + 1;
    end if;
  end loop;

  update public.campaign_jobs set status = 'done', finished_at = now(), records = v_created
  where campaign_id = p_campaign and step = 'normalize';
  if not found then
    insert into public.campaign_jobs (manufacturer_id, campaign_id, step, status, records, started_at, finished_at)
    values (v_campaign.manufacturer_id, p_campaign, 'normalize', 'done', v_created, now(), now())
    on conflict do nothing;
  end if;

  perform public.advance_campaign(p_campaign);
  return jsonb_build_object('created', v_created, 'merged', v_merged, 'review', v_review, 'rejected', v_rejected);
end
$$;

create or replace function public.create_prospect_from_raw(p_raw uuid)
returns uuid
language plpgsql security definer
set search_path = public, extensions
as $$
declare
  r public.raw_records%rowtype;
  v_campaign public.campaigns%rowtype;
  p jsonb;
  v_prospect uuid;
  v_contact uuid;
  v_phone text;
  v_type text;
begin
  select * into r from public.raw_records where id = p_raw;
  select * into v_campaign from public.campaigns where id = r.campaign_id;
  p := r.payload;
  v_phone := public.normalize_phone_e164(p ->> 'phone');
  v_type := lower(coalesce(p ->> 'type', 'distributor'));
  if v_type not in ('distributor', 'super_stockist', 'wholesaler', 'dealer', 'retailer', 'modern_trade', 'other') then
    v_type := 'other';
  end if;

  insert into public.prospects (manufacturer_id, campaign_id, name, normalized_name, type, category, address, city, state,
    pincode, geo, gstin, website, source_id, source_url, confidence, signals, research, pipeline_step, review_status)
  values (r.manufacturer_id, r.campaign_id, trim(p ->> 'name'), public.normalize_business_name(p ->> 'name'), v_type,
    p ->> 'category_hint', p ->> 'address', initcap(trim(coalesce(p ->> 'city', v_campaign.target_city))),
    coalesce(p ->> 'state', v_campaign.target_state), p ->> 'pincode',
    case when p ? 'lat' and p ? 'lng' and (p ->> 'lat') is not null
         then extensions.st_setsrid(extensions.st_makepoint((p ->> 'lng')::float8, (p ->> 'lat')::float8), 4326)::extensions.geography end,
    p ->> 'gstin', p ->> 'website', r.source_id, p ->> 'source_url',
    case when coalesce((p ->> 'verified')::boolean, false) or coalesce(p ->> 'source_url', '') <> '' then 'verified' else 'inferred' end,
    coalesce(p -> 'signals', '{}'::jsonb),
    jsonb_strip_nulls(jsonb_build_object('brands_carried', p -> 'brands', 'raw_description', p ->> 'description')),
    'classify', 'pending')
  returning id into v_prospect;

  if v_phone is not null or coalesce(p ->> 'contact_name', '') <> '' or coalesce(p ->> 'email', '') <> '' then
    insert into public.contacts (manufacturer_id, prospect_id, name, role, phone_e164, email, is_primary)
    values (r.manufacturer_id, v_prospect, p ->> 'contact_name', p ->> 'contact_role', v_phone, p ->> 'email', true)
    on conflict (manufacturer_id, phone_e164) where phone_e164 is not null do nothing
    returning id into v_contact;
    if v_contact is not null then
      insert into public.consents (manufacturer_id, contact_id, channel, status, source)
      values (r.manufacturer_id, v_contact, 'whatsapp', 'none', 'discovered')
      on conflict do nothing;
    end if;
  end if;

  if v_phone is null then
    update public.prospects set review_flags = array['missing_phone'], review_status = 'needs_review',
      attention_reason = coalesce(attention_reason, 'No valid phone number found')
    where id = v_prospect;
  end if;

  update public.raw_records set status = 'normalized', prospect_id = v_prospect where id = p_raw;
  perform pgmq.send('classify', jsonb_build_object('prospect_id', v_prospect));
  return v_prospect;
end
$$;

create or replace function public.set_prospect_classification(
  p_prospect uuid, p_category text, p_type text, p_confidence numeric, p_reason text default null
)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if not public.is_trusted() then
    perform public.app_error('forbidden', 'Workers only', null);
  end if;
  update public.prospects set
    category = coalesce(p_category, category),
    type = case when p_type in ('distributor', 'super_stockist', 'wholesaler', 'dealer', 'retailer', 'modern_trade', 'other')
                then p_type else type end,
    category_confidence = p_confidence,
    attention_reason = case when p_confidence < 0.7
                            then 'Low classification confidence (' || round(p_confidence, 2) || '): ' || coalesce(p_reason, '')
                            else attention_reason end,
    review_flags = case when p_confidence < 0.7
                        then (select array_agg(distinct f) from unnest(review_flags || array['low_classification_confidence']) f)
                        else review_flags end,
    pipeline_step = 'research'
  where id = p_prospect;
  perform public.refresh_review_status(p_prospect);
  perform pgmq.send('research', jsonb_build_object('prospect_id', p_prospect));
end
$$;

create or replace function public.set_prospect_research(p_prospect uuid, p_research jsonb, p_signals jsonb)
returns numeric
language plpgsql security definer
set search_path = public
as $$
declare
  v_score numeric;
  v_campaign uuid;
begin
  if not public.is_trusted() then
    perform public.app_error('forbidden', 'Workers only', null);
  end if;
  update public.prospects set
    research = research || coalesce(p_research, '{}'::jsonb),
    signals = signals || coalesce(p_signals, '{}'::jsonb),
    pipeline_step = 'score',
    last_checked_at = now()
  where id = p_prospect
  returning campaign_id into v_campaign;
  v_score := public.score_prospect(p_prospect);
  if v_campaign is not null then
    perform public.advance_campaign(v_campaign);
  end if;
  return v_score;
end
$$;

create or replace function public.set_stage(
  p_prospect uuid,
  p_to public.prospect_stage,
  p_note text default null,
  p_client_ts timestamptz default null,
  p_idempotency_key text default null
)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_prospect public.prospects%rowtype;
  v_result jsonb;
begin
  if p_idempotency_key is not null then
    select result into v_result from public.idempotency_keys where key = p_idempotency_key;
    if found then
      return v_result;
    end if;
  end if;

  select * into v_prospect from public.prospects where id = p_prospect for update;
  if not found then
    perform public.app_error('not_found', 'Prospect not found', 'prospect_id');
  end if;
  if not public.is_trusted() then
    if v_prospect.manufacturer_id is distinct from public.auth_mid() then
      perform public.app_error('forbidden', 'Prospect belongs to another manufacturer', 'prospect_id');
    end if;
    if public.auth_role() = 'rep' and v_prospect.assigned_rep_id is distinct from auth.uid() then
      perform public.app_error('forbidden', 'This lead is not assigned to you', 'prospect_id');
    end if;
    if public.auth_role() = 'system_admin' then
      perform public.app_error('forbidden', 'System administrators cannot move pipeline stages', 'prospect_id');
    end if;
  end if;

  if v_prospect.stage = p_to then
    v_result := jsonb_build_object('ok', true, 'stage', p_to, 'changed', false);
  else
    if p_to in ('first_order', 'repeat_order') and not public.is_trusted() then
      perform public.app_error('use_confirm_order', 'Orders move a prospect to First Order; confirm the PO instead', 'stage');
    end if;
    if not exists (select 1 from public.stage_transitions where from_stage = v_prospect.stage and to_stage = p_to) then
      perform public.app_error('invalid_transition',
        format('Cannot move from %s to %s', v_prospect.stage, p_to), 'stage');
    end if;
    update public.prospects set stage = p_to, stage_changed_at = now() where id = p_prospect;
    insert into public.prospect_events (manufacturer_id, prospect_id, kind, from_stage, to_stage, body, actor_id, client_ts)
    values (v_prospect.manufacturer_id, p_prospect, 'stage_change', v_prospect.stage, p_to, p_note, auth.uid(), p_client_ts);
    v_result := jsonb_build_object('ok', true, 'stage', p_to, 'changed', true, 'from', v_prospect.stage);
  end if;

  if p_idempotency_key is not null then
    insert into public.idempotency_keys (key, user_id, rpc, result)
    values (p_idempotency_key, auth.uid(), 'set_stage', v_result) on conflict (key) do nothing;
  end if;
  return v_result;
end
$$;

create or replace function public.profiles_guard()
returns trigger
language plpgsql
as $$
begin
  if public.is_trusted() then
    return new;
  end if;
  if public.auth_role() <> 'owner' and (new.role is distinct from old.role
      or new.approval_limit_paise is distinct from old.approval_limit_paise
      or new.active is distinct from old.active) then
    raise exception using errcode = 'P0001', message = 'forbidden', detail = 'Only an owner can change roles and limits';
  end if;
  if new.user_id = auth.uid() and new.role is distinct from old.role then
    raise exception using errcode = 'P0001', message = 'forbidden', detail = 'You cannot change your own role';
  end if;
  return new;
end
$$;

create or replace function public.queue_retry(p_queue text, p_msg_id bigint, p_read_ct integer, p_error text default null,
                                              p_max_attempts integer default 5)
returns text
language plpgsql security definer
set search_path = public
as $$
begin
  if p_read_ct >= p_max_attempts then
    perform pgmq.archive(p_queue, p_msg_id);
    perform public.notify_users(null, public.sysadmin_users(), 'dead_letter', 'Dead letter in ' || p_queue,
      left(coalesce(p_error, 'Retries exhausted'), 300), '/system/jobs', 'dead:' || p_queue || ':' || p_msg_id, '{in_app,email}');
    return 'archived';
  end if;
  perform pgmq.set_vt(p_queue, p_msg_id, least(3600, (power(2, p_read_ct) * 15)::integer));
  return 'retrying';
end
$$;

create or replace function public.sysadmin_queue_metrics()
returns table (queue_name text, queue_length bigint, oldest_msg_age_sec integer, total_messages bigint, dead_letters bigint)
language plpgsql security definer
set search_path = public
as $$
declare
  m record;
  v_dead bigint;
begin
  if not (public.is_system_admin() or public.is_trusted()) then
    perform public.app_error('forbidden', 'System administrators only', null);
  end if;
  for m in select * from pgmq.metrics_all() loop
    execute format('select count(*) from pgmq.%I', 'a_' || m.queue_name) into v_dead;
    queue_name := m.queue_name;
    queue_length := m.queue_length;
    oldest_msg_age_sec := m.oldest_msg_age_sec;
    total_messages := m.total_messages;
    dead_letters := v_dead;
    return next;
  end loop;
end
$$;

create or replace function public.sysadmin_dead_letters(p_limit integer default 100)
returns table (queue_name text, msg_id bigint, read_ct integer, enqueued_at timestamptz, archived_at timestamptz, message jsonb)
language plpgsql security definer
set search_path = public
as $$
declare
  q record;
begin
  if not public.is_system_admin() then
    perform public.app_error('forbidden', 'System administrators only', null);
  end if;
  for q in select queue_name as name from pgmq.list_queues() loop
    return query execute format(
      'select %L::text, msg_id, read_ct, enqueued_at, archived_at, message from pgmq.%I order by archived_at desc limit %s',
      q.name, 'a_' || q.name, p_limit);
  end loop;
end
$$;

create or replace function public.sysadmin_retry_dead_letter(p_queue text, p_msg_id bigint)
returns bigint
language plpgsql security definer
set search_path = public
as $$
declare
  v_msg jsonb;
  v_new bigint;
begin
  if not public.is_system_admin() then
    perform public.app_error('forbidden', 'System administrators only', null);
  end if;
  execute format('delete from pgmq.%I where msg_id = $1 returning message', 'a_' || p_queue) into v_msg using p_msg_id;
  if v_msg is null then
    perform public.app_error('not_found', 'Dead letter not found', 'msg_id');
  end if;
  v_new := pgmq.send(p_queue, v_msg);
  perform public.write_audit(null, 'sysadmin_retry_dead_letter', 'queue', null,
    jsonb_build_object('queue', p_queue, 'msg_id', p_msg_id, 'new_msg_id', v_new));
  return v_new;
end
$$;

create or replace function public.erase_contact(p_contact uuid, p_reason text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_contact public.contacts%rowtype;
  v_media text[];
  v_msgs integer;
begin
  if not (public.is_trusted() or public.auth_role() = 'owner') then
    perform public.app_error('forbidden', 'Only the company owner can erase personal data', null);
  end if;
  if coalesce(length(trim(p_reason)), 0) < 5 then
    perform public.app_error('reason_required', 'Record the erasure request reference', 'reason');
  end if;
  select * into v_contact from public.contacts where id = p_contact for update;
  if not found then
    perform public.app_error('not_found', 'Contact not found', 'contact_id');
  end if;
  if not public.is_trusted() and v_contact.manufacturer_id is distinct from public.auth_mid() then
    perform public.app_error('not_found', 'Contact not found', 'contact_id');
  end if;

  select coalesce(array_agg(m.media_path) filter (where m.media_path is not null), '{}') into v_media
  from public.messages m join public.conversations c on c.id = m.conversation_id
  where c.contact_id = p_contact;

  perform set_config('app.erasing', 'on', true);
  update public.messages m set body = '[erased]', media_path = null, template_params = null
  from public.conversations c
  where c.id = m.conversation_id and c.contact_id = p_contact;
  get diagnostics v_msgs = row_count;
  perform set_config('app.erasing', 'off', true);

  update public.conversations set last_message_preview = '[erased]' where contact_id = p_contact;
  delete from public.consents where contact_id = p_contact;
  update public.consent_events set evidence = null where contact_id = p_contact;
  update public.contacts set name = null, email = null, phone_e164 = null, role = null, erased_at = now()
  where id = p_contact;

  perform public.write_audit(v_contact.manufacturer_id, 'erase_contact', 'contact', p_contact,
    jsonb_build_object('reason', p_reason, 'messages', v_msgs));
  return jsonb_build_object('ok', true, 'messages_erased', v_msgs, 'media_paths', to_jsonb(v_media));
end
$$;

create or replace function public.enqueue_ai_turn(
  p_conversation uuid,
  p_reason text,
  p_trigger_message uuid default null,
  p_context jsonb default '{}'::jsonb
)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_mid uuid;
  v_id uuid;
begin
  select manufacturer_id into v_mid from public.conversations where id = p_conversation;
  if v_mid is null then
    return null;
  end if;
  if exists (select 1 from public.conversations c join public.prospects p on p.id = c.prospect_id
             where c.id = p_conversation and p.review_status = 'rejected') then
    perform public.notify_users(v_mid, public.permitted_users(v_mid, 'review_leads'), 'rejected_prospect_replied',
      'A rejected prospect sent a message', 'Reopen it in Lead Review if you want the AI to reply',
      '/leads?status=rejected', 'rejected_reply:' || p_conversation || ':' || to_char(now(), 'YYYYMMDD'), '{in_app}');
    return null;
  end if;
  insert into public.ai_turns (manufacturer_id, conversation_id, trigger_message_id, reason, context)
  values (v_mid, p_conversation, p_trigger_message, p_reason, coalesce(p_context, '{}'::jsonb))
  on conflict (trigger_message_id) do nothing
  returning id into v_id;
  if v_id is not null then
    perform pgmq.send('ai_turns', jsonb_build_object('turn_id', v_id));
  end if;
  return v_id;
end
$$;


-- ---------------------------------------------------------------------------
-- Remove the internal ops workflow functions
-- ---------------------------------------------------------------------------
drop function if exists public.approve_prospects(uuid[], text, text);
drop function if exists public.ops_update_prospect(uuid, jsonb);
drop function if exists public.resolve_merge_candidate(uuid, boolean);
drop function if exists public.ops_import_raw_records(uuid, jsonb);
drop function if exists public.ops_queue_metrics();
drop function if exists public.ops_dead_letters(integer);
drop function if exists public.ops_retry_dead_letter(text, bigint);
drop function if exists public.ops_users();
drop function if exists public.is_ops();

-- Live review history in open Lead Review screens.
alter publication supabase_realtime add table public.prospect_reviews, public.merge_candidates;

-- ---------------------------------------------------------------------------
-- Privileges: internal helpers stay private; the review RPCs are the API.
-- ---------------------------------------------------------------------------
revoke execute on function
  public.merge_prospects(uuid, uuid, text),
  public.log_review(uuid, text, public.review_status, public.review_status, text, jsonb),
  public.refresh_review_status(uuid),
  public.permitted_users(uuid, text),
  public.sysadmin_users()
from public, anon, authenticated;

grant execute on function
  public.is_system_admin(),
  public.has_permission(text),
  public.set_member_permissions(uuid, text[]),
  public.review_prospects(uuid[], text, text),
  public.update_prospect_details(uuid, jsonb, text),
  public.flag_prospect(uuid, text),
  public.resolve_duplicate(uuid, boolean, text),
  public.merge_prospect_records(uuid, uuid, text),
  public.assign_prospects(uuid[], uuid),
  public.import_prospect_records(uuid, jsonb, text),
  public.sysadmin_platform_health(),
  public.sysadmin_queue_metrics(),
  public.sysadmin_dead_letters(integer),
  public.sysadmin_retry_dead_letter(text, bigint)
to authenticated;
